content.text:
{
  "name": "Julabo 温度循环控制器",
  "name_en": "Julabo temperature circulator controller",
  "manufacturer": "JULABO",
  "description": "JULABO 温度循环控制设备是一类实验室台式液体温控装置，包括加热循环器、制冷/加热循环器、低温紧凑型循环器和再循环冷却器。它通过循环传热液体为外部设备或样品提供稳定的加热、制冷或恒温控制，常用于反应釜、冷凝器、分析仪器和其他需要精确温度管理的实验系统。",
  "description_en": "JULABO temperature circulation equipment is a family of benchtop liquid temperature control devices, including heating circulators, refrigerated/heating circulators, cryo-compact circulators, and recirculating coolers. They circulate a heat-transfer fluid to provide stable heating, cooling, or constant-temperature control for external equipment or samples, commonly used with reactors, condensers, analytical instruments, and other laboratory systems requiring precise temperature management.",
  "actions": [
    {
      "action_name": "auto-decode",
      "description": "解析设备返回的数据或报文。",
      "description_en": "Decode data or messages returned by the device."
    },
    {
      "action_name": "auto-write",
      "description": "向设备发送命令。",
      "description_en": "Send a command to the device."
    },
    {
      "action_name": "auto-write_readline",
      "description": "向设备发送命令并读取一行返回信息。",
      "description_en": "Send a command to the device and read a single-line response."
    }
  ],
  "tag_hints": [
    "temperature control",
    "liquid circulator",
    "recirculating chiller",
    "heating circulator",
    "refrigerated circulator",
    "lab cooling",
    "constant temperature bath"
  ]
}

